AD=A
KY='ÖSYM TYT Türkçe 2018–2026 · Paraf İQ · Sıfır Risk (paragrafta anlam: olumsuz kökler)'
KARTLAR={
 'K-PYAR-01':dict(alt='Ulaşılamayan Yargı',fikir='Dört şıkkı parçadaki karşılıklarıyla eşleyip karşılığı olmayan ya da parçayla çelişen yargıyı bulmak.',tuzak='Soru kökünü olumlu okuyup parçada var olan şıkkı seçmek; çelişkiyi fark etmemek.',zorluk='orta',kalip='düz',adim=3,tipId='prg-ulasilamaz',kaynak=KY),
 'K-PYAR-02':dict(alt='Dolaylı Anlatılan Yargılar',fikir='Parçadaki bilgilerin şıklarda başka sözcüklerle ifade edildiğini görüp yanlış ya da aşırı genellenmiş yargıyı ayırmak.',tuzak='Şıkta sözcük birebir geçmediği için doğru yargıyı yanlış sanmak.',zorluk='zor',kalip='düz',adim=4,tipId='prg-ulasilamaz',kaynak=KY),
 'K-PYAR-03':dict(alt='Parçada Geçmeyen Konu',fikir='Şıklardaki konuların her birinin parçada işlenip işlenmediğini sırayla denetleyip hiç geçmeyeni bulmak.',tuzak='Konuya yakın, doğru bilgiyi parçada varmış gibi sanmak.',zorluk='orta',kalip='düz',adim=3,tipId='prg-deginilmemis',kaynak=KY),
 'K-PYAR-04':dict(alt='Dolaylı Değinilen Konular',fikir='Parçada tek cümleyle ya da dolaylı biçimde geçen konuları fark edip gerçekten hiç geçmeyeni ayırmak.',tuzak='Yan cümlede geçen bir konuyu değinilmemiş sanmak; doğru bilgiyi parçada var saymak.',zorluk='zor',kalip='düz',adim=4,tipId='prg-deginilmemis',kaynak=KY),
 'K-PYAR-05':dict(alt='Söylenemeyen Yargı',fikir='Parçanın destekleyemediği ya da tersini söylediği yargıyı, desteklenen dört yargıdan ayırmak.',tuzak='Aşırı genelleme (yalnızca, tek yol, hiç) içeren şıkkı gözden kaçırmak.',zorluk='orta',kalip='düz',adim=3,tipId='prg-soylenemez',kaynak=KY),
 'K-PYAR-06':dict(alt='Kesin Çıkarım',fikir='Parçadaki bilgilerden mantıksal olarak çıkan tek yargıyı, akla yatkın ama parçada dayanağı olmayan yargılardan ayırmak.',tuzak='Parçanın söylemediği ama doğru görünen genellemeyi çıkarım saymak.',zorluk='orta',kalip='düz',adim=3,tipId='prg-cikarilabilir',kaynak=KY),
}
TIPLER={'prg-ulasilamaz':'Parçadan ulaşılamayan yargı','prg-deginilmemis':'Parçada değinilmeyen konu','prg-soylenemez':'Parçaya göre söylenemeyen yargı','prg-cikarilabilir':'Parçadan ulaşılabilen / çıkarılabilen yargı'}
Q=kur('pyar','Paragraf','tr|Paragraf',KARTLAR,TIPLER); Q.n=30

B_KOK=B('Olumsuz soru kökü','“ulaşılamaz, değinilmemiştir, söylenemez” köklerinde doğru şık parçaya uymayan şıktır; diğer dört şıkkın her biri parçada karşılık bulur. Örnek: parça “arı dansla haber verir” diyorsa “arı yalnız kokuyla haber verir” söylenemez')
B_DEG=B('Değinilmeyen konu','şık doğru bir bilgi olsa bile parçada hiç geçmiyorsa “değinilmemiştir”. Örnek: parça mercanın beslenmesini anlatıyorsa “mercanın kıyıyı koruduğu” bilgisi gerçek olsa da parçada yoktur')
B_CIK=B('Çıkarım','parçadan çıkarılabilen yargı, parçadaki bilgilerden mantıkla ulaşılan yargıdır; parçada olmayan ya da aşırı genelleyen şık çıkarılamaz. Örnek: “Su bitkileri yaşatır” parçasından “su olmayan yerde bitki yaşamaz” kesin çıkmaz')
B_GEN=B('Aşırı genelleme','“yalnızca, her zaman, tümüyle, hiçbir” gibi kesin sözcükler içeren yargı çoğu kez parçanın söylediğinden fazlasını iddia eder. Örnek: “çoğu kuş göç eder” parçasından “bütün kuşlar göç eder” çıkarılamaz')
PUF={'U':['Olumsuz kökte şıkları tek tek parçada ara; karşılığı bulunamayan ya da çelişen şık cevaptır.','Olumsuz soruda dört şıkkı parçadan “var” diye işaretle, işaretsiz kalanı seç.'],
 'D':['“Değinilmemiştir” sorusunda doğru bilgi olması yetmez; parçada geçip geçmediğine bak.','Konu başlıklarını parçadan çıkarıp şıklarla eşleştir, eşleşmeyen konu cevaptır.'],
 'S':['“Söylenemez” sorularında “yalnızca, tek, tümüyle” gibi kesin sözcük taşıyan şıka dikkat et.','Dört şıkkı parçadaki cümlelerle eşle; eşleşmeyen ya da tersi söylenen şık cevaptır.'],
 'C':['Çıkarımda parçanın kesin söylediğinden bir adım ötesine geçen şık çıkarılamaz.','Çıkarım sorusunda parçada dayanağı bulunan şıkkı seç; yalnızca akla yatkın olan yeterli değildir.']}
ISTENEN={'U':'Parçadan çıkarılamayan yargı.','D':'Parçada hiç değinilmeyen konu.','S':'Parçayla uyuşmayan (söylenemeyen) yargı.','C':'Parçadan çıkarılabilen yargı.'}
KOKLER={'U':'Bu parçadan aşağıdakilerin hangisine ulaşılamaz?','D':'Bu parçada aşağıdakilerden hangisine değinilmemiştir?','S':'Bu parçaya göre aşağıdakilerden hangisi söylenemez?','C':'Bu parçadan aşağıdakilerin hangisine ulaşılabilir?'}
HARF=list('ABCDE')*6; random.Random(11).shuffle(HARF)
SAY=[0]
def kelime(m): return len(m.split())

def Z(kart,zor,kazanim,t,metin,dogru,neden,yanlis,ip,ozet,kok=None):
    SAY[0]+=1; no='%04d'%SAY[0]; harf=HARF[SAY[0]-1]
    k=kelime(metin); print(no,zor,t,k,'kelime')
    if not 60<=k<=150 or (zor=='zor' and k<100) or (zor=='kolay' and k>90): print('  UYARI uzunluk',no,k)
    assert len(yanlis)==4
    L=[x for x in 'ABCDE' if x!=harf]; opts=[None]*5
    if t=='C':
        opts['ABCDE'.index(harf)]=(dogru,'çıkar','','')
        for l,(m,c) in zip(L,yanlis): opts['ABCDE'.index(l)]=(m,'yok',c,'bilgi')
        pred=lambda e:e=='çıkar'
    else:
        opts['ABCDE'.index(harf)]=(dogru,'yok','','')
        for l,(m,d) in zip(L,yanlis): opts['ABCDE'.index(l)]=(m,'var',f'Parçada karşılığı var: {d}. Soru parçada olmayanı sorduğu için bu şık elenir.','dikkat')
        pred=lambda e:e=='yok'
    uz=[len(o[0]) for o in opts]; i=uz.index(max(uz))
    if uz.count(max(uz))==1 and 'ABCDE'[i]==harf: print('UYARI doğru şık en uzun',no,[ (o[0],len(o[0])) for o in opts])
    if t=='C':
        isl=' · '.join(f'{l}: '+('çıkarılır ✓' if l==harf else 'dayanaksız') for l in 'ABCDE')
        ad=[AD('Parçayı özetle',f'Parça, {ozet} anlatıyor. Önce bu ana çizgiyi kur.',f'konu: {ozet}'),
            AD('Soru kökünü çöz','“Ulaşılabilir” kökünde doğru şık, parçadaki bilgilerden mantıkla çıkan yargıdır.','doğru şık = parçadan çıkan'),
            AD('Şıkları ele','Her şıkkı parçadaki cümlelerle karşılaştır; parçanın söylediğinden öteye geçen şıkları ele.',isl),
            AD('Sonucu bağla',neden,f'{harf}: doğru')]
    else:
        isl=' · '.join(f'{l}: '+('yok ✓' if l==harf else 'var') for l in 'ABCDE')
        ad=[AD('Parçayı özetle',f'Parça, {ozet} anlatıyor. Önce bu ana çizgiyi kur.',f'konu: {ozet}'),
            AD('Soru kökünü çöz','Kök olumsuz: doğru şık parçada karşılığı olmayan ya da parçayla çelişen şıktır.','doğru şık = parçada yok'),
            AD('Şıkları ele','Dört şık parçada açıkça karşılık bulur; yalnızca biri bulmaz.',isl),
            AD('Sonucu bağla',neden,f'{harf}: doğru')]
    bilgi=[B_CIK,B_GEN] if t=='C' else ([B_KOK,B_DEG] if t=='D' else [B_KOK])
    puf=PUF[t][SAY[0]%2]
    soru(Q,no,kart,zor,kazanim,{'kolay':2,'orta':3,'zor':4}[zor],metin+'\n'+(kok or KOKLER[t]),opts,harf,pred,ISTENEN[t],ip,bilgi,ad,puf)

# ---------------- ULAŞILAMAZ (10) ----------------
Z('K-PYAR-01','kolay','Parçayla çelişen yargıyı belirler.','U',
 'Bal arıları yiyecek bulduklarında bunu kovandaki arkadaşlarına bir dansla bildirir. Arı, kovana dönünce petek üzerinde sekiz çizen bir yol izleyerek dans eder; dansın yönü yiyeceğin güneşe göre konumunu, süresi ise uzaklığını gösterir. Dansı izleyen işçi arılar bu bilgiyle doğru çiçek kümesine uçar. Böylece yüzlerce arının rastgele aramasına gerek kalmaz ve kovan, enerjisini yiyecek toplamaya yöneltir. Bu iletişim biçimi, kovanın bir arada çalışan bir topluluk gibi davranmasını sağlar.',
 'Arılar yiyeceğin yerini yalnızca kokuyla anlatır.','Parça, haberin dansla verildiğini söyler; “yalnızca koku” yargısı parçayla çelişir.',
 [('Yiyeceğin yeri, kovandaki arılara dansla bildirilir.','“yiyecek bulduklarında bunu… bir dansla bildirir”'),('Dansın yönü, yiyeceğin güneşe göre yerini gösterir.','“dansın yönü yiyeceğin güneşe göre konumunu… gösterir”'),('Dansın süresi, yiyeceğe olan uzaklığı bildirir.','“süresi ise uzaklığını gösterir”'),('Dans, arıların boşuna arama yapmasını gereksiz kılar.','“rastgele aramasına gerek kalmaz”')],
 'Şıkları tek tek parçadaki cümlelerle eşleştir; birinin karşılığı yok.','arıların yiyecek yerini dansla bildirmesini')
Z('K-PYAR-01','kolay','Parçayla çelişen yargıyı belirler.','U',
 'Yarasalar geceleri karanlıkta avlanır, ama yollarını gözleriyle değil sesle bulur. Çok yüksek frekanslı sesler çıkarır ve bu seslerin çevredeki cisimlere çarpıp dönüşünü dinlerler. Sesin dönme süresi cismin uzaklığını, yankının biçimi de cismin ne olduğunu anlatır. Bu yöntem sayesinde yarasa, bir böceği ağaç dalından ayırabilir. İnsan kulağı bu sesleri duyamaz. Bu sayede yarasalar, mağaralar gibi tümüyle karanlık yerlerde bile engellere çarpmadan uçabilir. Bu beceri, onları gece avcıları arasında başarılı kılan en önemli özelliklerden biridir.',
 'Yarasalar, avlanırken en çok görme duyusuna güvenir.','Parça, yarasaların yolunu “gözleriyle değil sesle” bulduğunu söyler; şık parçayla çelişir.',
 [('Yarasalar, yollarını sesin yansımasıyla bulur.','“yollarını… sesle bulur”, “seslerin… dönüşünü dinlerler”'),('Sesin dönüş süresi, cismin uzaklığı hakkında bilgi verir.','“sesin dönme süresi cismin uzaklığını… anlatır”'),('Yankının biçimi, cismin türünü ayırt etmeye yarar.','“yankının biçimi de cismin ne olduğunu anlatır”'),('Yarasaların çıkardığı sesler insan kulağınca duyulamaz.','“İnsan kulağı bu sesleri duyamaz”')],
 'Yarasanın yönünü neyle bulduğunu parçadan işaretle, sonra şıkları sına.','yarasaların sesle yön bulmasını')
Z('K-PYAR-01','orta','Parçada olmayan yargıyı belirler.','U',
 'Uyku, dinlenmekten ibaret pasif bir durum sanılır. Oysa beyin uyurken gün boyu edinilen bilgileri yeniden işler: Önemli görülen izler güçlendirilir, gereksiz görülenler silikleşir. Derin uykuda yeni öğrenilen bilgi kalıcı belleğe yerleşmeye başlar. Bu yüzden sınavdan önceki gece sabaha kadar çalışıp hiç uyumayan öğrenci, öğrendiklerini çoğu zaman kalıcı kılamaz. Uykusuzluk yalnızca dikkati değil, öğrenmenin kalıcılığını da zayıflatır. Bu nedenle uzmanlar, düzenli ve yeterli uykuyu öğrenmenin ayrılmaz bir parçası olarak görür. Dinlenmiş bir beyin, yeni bilgiyi daha kolay alır.',
 'Uyku sırasında beyin, bilgi işlemeye tümüyle ara verir.','Parça, beynin uykuda bilgiyi “yeniden işlediğini” söyler; şık parçayla çelişir.',
 [('Derin uyku, yeni bilginin kalıcı belleğe geçişini başlatır.','“Derin uykuda… kalıcı belleğe yerleşmeye başlar”'),('Beyin, uykuda önemsiz görülen izleri zayıflatabilir.','“gereksiz görülenler silikleşir”'),('Uykusuzluk, dikkatin yanında kalıcı öğrenmeyi de bozar.','“yalnızca dikkati değil, öğrenmenin kalıcılığını da zayıflatır”'),('Uyku, sanıldığı gibi tümüyle edilgin bir durum değildir.','“pasif bir durum sanılır. Oysa…”')],
 'Uykuda beynin ne yaptığını anlatan cümleyi bul.','uykunun belleği pekiştirmedeki rolünü')
Z('K-PYAR-01','orta','Parçada olmayan yargıyı belirler.','U',
 'Antibiyotikler, bakterilerin çoğalmasını durduran ya da onları öldüren ilaçlardır; ancak her kullanımda hayatta kalan birkaç bakteri vardır. Bu bakteriler ilaca dayanıklı oldukları için çoğalır ve yeni nesillere bu özelliklerini aktarır. Gereksiz ya da yarım bırakılan tedaviler bu süreci hızlandırır. Virüslerin yol açtığı soğuk algınlığı gibi hastalıklarda antibiyotik hiçbir işe yaramaz; buna karşın gereksiz kullanım direnç sorununu büyütür. Bu nedenle antibiyotikler yalnızca doktorun gerekli gördüğü durumlarda ve önerilen süre boyunca kullanılmalıdır. Aksi hâlde yeni ilaçlar bulunsa bile bakteriler bir adım önde olabilir.',
 'Dirençli bakteriler, ilaç bırakılınca duyarlı hâle döner.','Parça, dirençli özelliğin yeni nesillere aktarıldığını söyler; kendiliğinden geri dönüş parçada yoktur.',
 [('Her antibiyotik kullanımında dayanıklı bakteriler sağ kalabilir.','“her kullanımda hayatta kalan birkaç bakteri vardır”'),('Dirençli bakteriler, özelliklerini sonraki nesillere geçirir.','“yeni nesillere bu özelliklerini aktarır”'),('Yarım bırakılan tedavi, direncin yayılmasını hızlandırır.','“yarım bırakılan tedaviler bu süreci hızlandırır”'),('Virüs kaynaklı hastalıklarda antibiyotikten yarar sağlanmaz.','“antibiyotik hiçbir işe yaramaz”')],
 'Dirençli bakterilerin akıbetini anlatan cümleye odaklan.','antibiyotik direncinin nasıl geliştiğini')
Z('K-PYAR-01','orta','Parçayla çelişen yargıyı belirler.','U',
 'Göçmen kuşlar binlerce kilometre öteden, her yıl aynı bölgeye döner. Bu yön bulma becerisinin arkasında birden çok ipucu vardır. Gündüz göç eden kuşlar güneşin konumunu, gece göç edenler ise yıldızların dizilişini rehber alır. Dünya’nın manyetik alanını algılayabilen türler de vardır; bu alan, bulutlu havada bile bir pusula işlevi görür. Genç kuşlar ilk göçte yolu deneyimli kuşlardan öğrenirken bazı türlerde yol bilgisi kalıtımla gelir. Bu çok katmanlı sistem, kuşların uzun yolculuklarda yolunu şaşırma olasılığını azaltır.',
 'Göçmen kuşlar yönlerini yalnızca güneşe bakarak bulur.','Parça, yön bulmada “birden çok ipucu” bulunduğunu söyler; “yalnızca güneş” yargısı parçayla çelişir.',
 [('Yön bulmada tek bir ipucu değil, birden çok ipucu rol oynar.','“birden çok ipucu vardır”'),('Gece göç eden kuşlar, yıldızların dizilişinden yararlanır.','“gece göç edenler ise yıldızların dizilişini rehber alır”'),('Manyetik alan, bulutlu havada da yön bulmaya yardım eder.','“bulutlu havada bile bir pusula işlevi görür”'),('Bazı kuş türlerinde yol bilgisi kalıtımla aktarılır.','“bazı türlerde yol bilgisi kalıtımla gelir”')],
 'Kuşların yön bulma yollarını sayan cümleleri işaretle.','göçmen kuşların yön bulma yollarını')
Z('K-PYAR-01','orta','Parçada olmayan yargıyı belirler.','U',
 'Kutuplardaki kalın buz tabakaları, yıllar boyu üst üste yağan karın sıkışmasıyla oluşur. Her kar katmanı, yağdığı dönemin havasından küçük kabarcıklar hapseder. Bilim insanları buzdan çıkardıkları silindir biçimli örneklerde bu kabarcıkları inceleyerek geçmişteki hava bileşimini ve sıcaklık değişimlerini okur. Daha derinden alınan örnekler daha eski dönemlere aittir. Böylece yüz binlerce yıl öncesinin iklimi hakkında doğrudan kayıt elde edilir. Bu kayıtlar, günümüzdeki ısınmanın geçmiştekilerle karşılaştırılmasına da olanak tanır.',
 'Buz örnekleri, yalnızca son yüzyılın iklimini yansıtır.','Parça, yüz binlerce yıl öncesine ait kayıt elde edildiğini söyler; “yalnızca son yüzyıl” yargısı parçayla çelişir.',
 [('Buz tabakaları, üst üste biriken karın sıkışmasıyla oluşur.','“üst üste yağan karın sıkışmasıyla oluşur”'),('Her kar katmanı, kendi döneminin havasından örnek saklar.','“yağdığı dönemin havasından küçük kabarcıklar hapseder”'),('Buzun derinlerinden alınan örnekler daha eski dönemleri yansıtır.','“Daha derinden alınan örnekler daha eski dönemlere aittir”'),('Buz örnekleri, geçmişteki sıcaklık değişimleri hakkında bilgi verir.','“sıcaklık değişimlerini okur”')],
 'Buz örneklerinin hangi zaman aralığını yansıttığını parçadan bul.','buz örneklerinden geçmiş iklimin okunmasını')
Z('K-PYAR-01','orta','Parçayla çelişen yargıyı belirler.','U',
 'Şehir ışıkları geceyi aydınlatırken doğanın karanlığa duyduğu gereksinimi de ortadan kaldırıyor. Yapay ışık, yıldızların görünmesini engellemenin ötesinde canlıların ritmini bozuyor. Yavru deniz kaplumbağaları denize ulaşmak için parlak ufku izler; kıyıdaki lambalar onları karaya yöneltebilir. Gece göç eden kuşlar aydınlık yapılara çarpar. İnsanda ise gece boyu ışığa maruz kalmak uyku düzenini ve hormon salgısını etkileyebilir. Sorunun çözümü, ışığı yalnızca gerektiği yerde ve gerektiği kadar kullanmaktır.',
 'Işık kirliliği, yalnızca insanın yaşamını etkileyen bir sorundur.','Parça, kaplumbağa ve kuşların da etkilendiğini anlatır; “yalnızca insan” yargısı parçayla çelişir.',
 [('Yapay ışık, gök cisimlerinin izlenmesini güçleştirir.','“yıldızların görünmesini engellemenin ötesinde…”'),('Kıyıdaki parlak lambalar, yavru kaplumbağaları yanlış yöne çekebilir.','“lambalar onları karaya yöneltebilir”'),('Aydınlatılmış binalar, göçmen kuşlar için tehlike oluşturur.','“Gece göç eden kuşlar aydınlık yapılara çarpar”'),('Gece ışığı, insanın uyku düzenini bozabilir.','“uyku düzenini ve hormon salgısını etkileyebilir”')],
 'Parçada etkilenen canlıların hangileri olduğunu listele.','yapay ışığın canlılar üzerindeki etkisini')
Z('K-PYAR-01','orta','Parçayla çelişen yargıyı belirler.','U',
 'Bir ormanda ağaçlar birbirinden bağımsız duran varlıklar gibi görünür; oysa toprağın altında durum farklıdır. Kökler, mantar iplikleriyle sarılmış bir ağ oluşturur. Mantar, ağaçtan şeker alır; karşılığında toprağın derinlerinden su ve mineral taşır. Bu ağ üzerinden bir ağaçtan ötekine besin ve bazı kimyasal uyarılar geçebilir. Bilim insanları, bu bağlantıların gölgede kalan fidanların hayatta kalmasına yardım ettiğini düşünüyor. Ancak bağlantının her ormanda aynı ölçüde işlediği henüz kanıtlanmış değildir.',
 'Mantarlar, ağaçlardan yararlanıp hiçbir şey vermez.','Parça, mantarın karşılığında su ve mineral taşıdığını söyler; şık parçayla çelişir.',
 [('Ağaç kökleri, mantar iplikleriyle bir ağ kurar.','“Kökler, mantar iplikleriyle sarılmış bir ağ oluşturur”'),('Mantar, ağaçtan aldığı şekere karşılık su ve mineral sağlar.','“karşılığında… su ve mineral taşır”'),('Ağaçlar arasında besin ve uyarı geçişi olabilir.','“besin ve bazı kimyasal uyarılar geçebilir”'),('Bu ağın her ormanda aynı biçimde çalıştığı kanıtlanmamıştır.','“her ormanda aynı ölçüde işlediği henüz kanıtlanmış değildir”')],
 'Mantarla ağaç arasındaki alışverişi anlatan cümleyi bul.','ağaçlar ile mantarlar arasındaki yer altı ağını')
Z('K-PYAR-02','zor','Dolaylı anlatılan yargılardan parçayla çelişeni belirler.','U',
 'Hava durumu tahminleri, atmosferin fizik yasalarıyla çalışan bilgisayar modellerine dayanır. Model, bugünkü sıcaklık, nem ve rüzgâr ölçümlerini başlangıç değeri alıp bunları ileriye doğru hesaplar. Sorun, atmosferin başlangıç koşullarındaki küçücük bir hatanın zamanla büyüyen bir sapmaya dönüşmesidir. Bu yüzden önümüzdeki bir iki günün tahmini oldukça güvenilirken on günü aşan tahminlerin isabeti hızla düşer. Daha çok ölçüm istasyonu ve daha güçlü bilgisayar hatayı azaltır, ama tümüyle ortadan kaldırmaz; çünkü ölçümü ne kadar inceltirsek inceltelim, daha da ince bir ayrıntı kalmaya devam eder. Bu nedenle meteorologlar tek bir hesap yerine, başlangıç değerleri çok az değiştirilmiş onlarca hesabı birlikte çalıştırır ve sonuçların birbirine ne kadar yakın çıktığına bakarak tahminin güvenilirliğini yorumlar.',
 'Güçlü bilgisayarlar, uzun vadeli tahminleri kesinleştirmiştir.','Parça, hatanın “tümüyle ortadan kalkmadığını” söyler; kesin doğruluk yargısı parçayla çelişir.',
 [('Tahmin modelleri, ölçüm sonuçlarını hesabın başlangıç noktası yapar.','“bugünkü… ölçümlerini başlangıç değeri alıp… hesaplar”'),('Başlangıçtaki küçük bir hata, zamanla daha büyük bir sapmaya dönüşebilir.','“küçücük bir hatanın zamanla büyüyen bir sapmaya dönüşmesi”'),('Kısa vadeli tahminler, uzun vadelilere göre daha güvenilirdir.','“bir iki günün tahmini oldukça güvenilirken on günü aşan… isabeti hızla düşer”'),('Ölçüm sayısını artırmak, tahmin hatasını tümüyle sıfırlamaz.','“hatayı azaltır, ama tümüyle ortadan kaldırmaz”')],
 'Parçada “ama” ile sınırlanan yargıyı bul; hangi şık o sınırı aşıyor?','hava tahminlerinin güvenilirliğinin sınırlarını')
Z('K-PYAR-02','zor','Dolaylı anlatılan yargılardan parçayla çelişeni belirler.','U',
 'Plastik atıklar doğada yok olmaz; güneş, dalga ve sürtünmeyle ufalanarak milimetreden küçük parçacıklara, yani mikroplastiklere dönüşür. Bu parçacıklar yalnız denizlerde değil, içme suyunda ve toprakta da bulunur. Küçük canlılar onları besin sanıp yutar; besin zincirinin üst basamaklarına çıkıldıkça parçacıklar canlıların dokularında birikebilir. Mikroplastiklerin insan sağlığına etkisi henüz tam bilinmiyor; ancak kaynağı kesmek, temizlemekten çok daha kolaydır: Bir kez suya karışan parçacıkları geri toplamak neredeyse imkânsızdır. Bu yüzden sorunun çözümünde bireysel alışkanlıkların yanında üretimi ve atık yönetimini düzenleyen kurallar da belirleyici olur. Kıyı temizlikleri görünen atığı azaltır; ama sudaki görünmez parçacıkları ortadan kaldırmaya yetmez. Bu belirsizlik, önlem almayı ertelemek için değil, tersine temkinli davranmak için gerekçe sayılır.',
 'Mikroplastiğin insan sağlığına zararı kanıtlanmıştır.','Parça, etkinin “henüz tam bilinmediğini” söyler; “kesin kanıt” yargısı parçayla çelişir.',
 [('Plastikler, parçalanarak mikroplastik hâline gelir.','“ufalanarak… mikroplastiklere dönüşür”'),('Mikroplastikler, denizlerin dışındaki ortamlarda da bulunur.','“içme suyunda ve toprakta da bulunur”'),('Küçük canlılar, mikroplastikleri yanlışlıkla besin sanabilir.','“besin sanıp yutar”'),('Mikroplastik sorununda önlemek, toplamaktan daha uygulanabilirdir.','“kaynağı kesmek, temizlemekten çok daha kolaydır”')],
 'Parçada belirsiz bırakılan konuyu bul; hangi şık onu kesin gibi sunuyor?','mikroplastiklerin yayılımını ve önlenme yolunu')

# ---------------- DEĞİNİLMEMİŞTİR (10) ----------------
Z('K-PYAR-03','kolay','Parçada hiç geçmeyen konuyu belirler.','D',
 'Mercan resifleri, okyanus tabanının çok küçük bir bölümünü kaplar; ama deniz türlerinin önemli bir kısmı yaşamını bu resiflerde sürdürür. Mercanların dokusunda yaşayan tek hücreli algler, fotosentezle mercana besin sağlar. Deniz suyu aşırı ısındığında algler mercanı terk eder ve mercan beyazlaşır. Beyazlaşma uzun sürerse mercan ölür; resife bağımlı balıklar da barınak ve besin kaybeder. Bu nedenle bilim insanları resiflerin sağlığını, deniz suyunun sıcaklığına bakarak da izler.',
 'Resiflerin kıyıyı dalgalardan koruduğuna','“Kıyının korunması” konusu parçada hiç geçmez; yalnızca resifin türler, algler, ısınma ve balıklar üzerindeki durumu anlatılır.',
 [('Resiflerin deniz türleri açısından taşıdığı öneme','“deniz türlerinin önemli bir kısmı yaşamını bu resiflerde sürdürür”'),('Algin mercana besin sağladığına','“algler, fotosentezle mercana besin sağlar”'),('Aşırı ısınmanın mercanı beyazlattığına','“Deniz suyu aşırı ısındığında… mercan beyazlaşır”'),('Mercan ölümünün resif balıklarını da etkilediğine','“balıklar da barınak ve besin kaybeder”')],
 'Parçanın işlediği konuları sırala; şıklardan hangisi bu sıraya girmiyor?','mercan resiflerinin yapısını ve beyazlaşmasını',
 kok='Bu parçada aşağıdakilerden hangisine değinilmemiştir?')
Z('K-PYAR-03','orta','Parçada hiç geçmeyen konuyu belirler.','D',
 'Rüzgâr türbinleri, havanın hareket enerjisini kanatlarla yakalayıp elektriğe çevirir. Yakıt yakmadıkları için çalışırken havaya sera gazı salmazlar. Ancak rüzgâr her zaman esmez; bu nedenle türbinlerin ürettiği elektrik gün içinde dalgalanır. Bu dalgalanmayı dengelemek için fazla üretim pillerde depolanır ya da diğer santrallerle birlikte yönetilir. Türbinlerin yerleştirileceği bölge seçilirken rüzgârın yıl boyunca ortalama hızına bakılır. Bu özellikleriyle rüzgâr enerjisi, elektrik üretiminde payı giderek artan yöntemlerden biridir.',
 'Türbinlerin kuşlar için taşıdığı tehlikeye','Kuşlara yönelik tehlike parçada hiç geçmez; öteki dört konu parçada ayrı ayrı işlenir.',
 [('Türbinlerin çalışırken sera gazı salmadığına','“havaya sera gazı salmazlar”'),('Rüzgârın sürekli esmemesinin sonucuna','“rüzgâr her zaman esmez; bu nedenle… dalgalanır”'),('Fazla elektriğin depolanabileceğine','“fazla üretim pillerde depolanır”'),('Yer seçiminde rüzgâr hızının önemine','“bölge seçilirken rüzgârın… ortalama hızına bakılır”')],
 'Her şık için parçada bir cümle işaretle; cümle bulunamayan şık cevaptır.','rüzgâr türbinlerinin çalışmasını ve sınırlarını')
Z('K-PYAR-03','orta','Parçada hiç geçmeyen konuyu belirler.','D',
 'Aşı, vücudu bir hastalık etkenine karşı önceden hazırlayan bir eğitimdir: Bağışıklık sistemi etkenin zayıflatılmış ya da etkisiz bir örneğini tanır ve gerçek karşılaşmada hızla yanıt verir. Aşının yararı yalnız aşılanan kişiyle sınırlı kalmaz. Toplumda yeterince çok kişi bağışık olduğunda hastalık yayılacak yer bulamaz; aşı olamayan bebekler ya da bağışıklığı zayıf kişiler de korunmuş olur. Bu duruma toplum bağışıklığı denir. Aşılama programlarının başarısı, bu nedenle çoğu zaman kişilerin tek tek korunmasından çok toplumun genel koruma düzeyiyle ölçülür.',
 'Aşıların geliştirilme sürecinin uzunluğuna','Aşı geliştirme süreci parçada hiç geçmez; öteki dört konu parçada işlenir.',
 [('Aşının bağışıklık sistemini önceden hazırladığına','“önceden hazırlayan bir eğitimdir”'),('Aşıda kullanılan etken örneğinin zayıflatıldığına','“zayıflatılmış ya da etkisiz bir örneğini”'),('Aşının aşı olmayanlara da dolaylı yarar sağlayabildiğine','“aşı olamayan bebekler… de korunmuş olur”'),('Toplum bağışıklığının adlandırıldığına','“Bu duruma toplum bağışıklığı denir”')],
 'Parçanın dört ayrı konusunu çıkar; beşinci konu hangisi?','aşının ve toplum bağışıklığının nasıl işlediğini')
Z('K-PYAR-03','orta','Parçada hiç geçmeyen konuyu belirler.','D',
 'Yağmur ve kar suyunun bir kısmı toprağa sızar, geçirimsiz bir tabakaya ulaşana kadar aşağı iner ve orada birikir. Bu birikime yer altı suyu denir. Kaynaklar, kuyular ve pek çok akarsu yer altı suyundan beslenir. Yer altı suyu yavaş yenilenir: Yüzyıllar içinde dolmuş bir depodan çekilen su, bir mevsimde geri gelmez. Sulama ve içme için gereğinden fazla su çekildiğinde seviye düşer, kuyular kurur.',
 'Yer altı suyunun kirlenme yollarına','Kirlenme parçada hiç geçmez; öteki dört konu parçada yer alır.',
 [('Yer altı suyunun nasıl oluştuğuna','“toprağa sızar… orada birikir”'),('Geçirimsiz tabakanın birikimdeki rolüne','“geçirimsiz bir tabakaya ulaşana kadar”'),('Kuyuların yer altı suyuna bağlı olduğuna','“Kaynaklar, kuyular… yer altı suyundan beslenir”'),('Yer altı suyunun yavaş yenilendiğine','“Yer altı suyu yavaş yenilenir”')],
 'Parçadaki bilgileri tek tek yaz ve şıklarla eşleştir.','yer altı suyunun oluşumunu ve tükenmesini')
Z('K-PYAR-03','kolay','Parçada hiç geçmeyen konuyu belirler.','D',
 'Uzaya gönderilen uydular, işlerini bitirdiğinde yörüngede bırakılır. Parçalanmış roket kademeleri ve bozulan araçlar da buraya eklenir. Bu parçalar saniyede kilometrelerce hızla döndüğünden küçük bir vida bile bir uyduya ciddi hasar verebilir. Çöplerin sayısı arttıkça birbirine çarpıp yeni parçalar doğurması kolaylaşır. Bu yüzden yeni uydular, görevini bitirince yörüngeden çıkarılacak biçimde tasarlanıyor. Uzmanlar, yörüngelerin bu kadar kalabalıklaşmasını gelecekteki uzay çalışmalarının önündeki ciddi bir engel olarak görüyor.',
 'Çöplerin insanlara verebileceği zarara','İnsanlara zarar verme olasılığı parçada hiç geçmez; öteki dört konu parçada işlenir.',
 [('Çöplerin başlıca kaynaklarına','“uydular… roket kademeleri ve bozulan araçlar”'),('Küçük parçaların bile hasar verebileceğine','“küçük bir vida bile… ciddi hasar verebilir”'),('Çarpışmaların çöp miktarını çoğaltabileceğine','“çarpıp yeni parçalar doğurması kolaylaşır”'),('Yeni uydularda alınan önleme','“yörüngeden çıkarılacak biçimde tasarlanıyor”')],
 'Şıklardaki konuları parçada sırayla ara.','uzay çöplerinin kaynağını ve yarattığı tehlikeyi')
Z('K-PYAR-03','orta','Parçada hiç geçmeyen konuyu belirler.','D',
 'Bitkiyi sulamanın en eski yolu tarlayı baştan sona suyla doldurmaktır; ancak bu yöntemde suyun büyük bölümü buharlaşır ya da köklerin ulaşamayacağı derinliğe sızar. Damla sulamada ise ince borularla su doğrudan bitkinin kök bölgesine, damla damla verilir. Böylece aynı ürün için çok daha az su harcanır. Yaprakların ıslanmaması, bazı mantar hastalıklarının yayılmasını da engeller. Bu yöntemin kurulum maliyeti yüksektir; ama su kıt olan bölgelerde masraf zamanla karşılanır.',
 'Damla sulamanın gübre dağıtımında da kullanılabileceğine','Gübreleme parçada hiç geçmez; öteki dört konu parçada işlenir.',
 [('Tarlayı suyla doldurmada suyun boşa gittiği yollara','“büyük bölümü buharlaşır ya da… derinliğe sızar”'),('Damla sulamada suyun kök bölgesine ulaştırıldığına','“doğrudan bitkinin kök bölgesine… verilir”'),('Yaprakların ıslanmamasının hastalıklar açısından yararına','“bazı mantar hastalıklarının yayılmasını da engeller”'),('Kurulum masrafının zamanla karşılanabileceğine','“masraf zamanla karşılanır”')],
 'Parçada anlatılan avantaj ve dezavantajları listele.','damla sulamanın tarla sulamaya göre üstünlüğünü')
Z('K-PYAR-03','orta','Parçada hiç geçmeyen konuyu belirler.','D',
 'İnsan bağırsağında trilyonlarca mikroorganizma yaşar. Bunların çoğu zararsız, hatta yararlıdır: Lifleri parçalar, bazı vitaminlerin üretimine katkı sağlar ve zararlı bakterilerin yerleşmesini zorlaştırır. Bağırsak florasının bileşimi kişiden kişiye değişir; beslenme alışkanlığı bu bileşimi etkileyen etmenlerden biridir. Antibiyotik kullanımı ise yararlı bakterileri de azaltarak dengeyi bozabilir. Bu yüzden ilaçları yalnızca doktor önerdiğinde ve önerdiği sürece kullanmak önemlidir. Sağlıklı bir bağırsak florası, bu nedenle genel sağlığın sessiz ama önemli bir parçası sayılır.',
 'Bağırsak florasının doğumla birlikte oluşmaya başladığına','Florenin oluşma zamanı parçada hiç geçmez; öteki dört konu parçada yer alır.',
 [('Bağırsak mikroplarının çoğunun zararsız ya da yararlı olduğuna','“Bunların çoğu zararsız, hatta yararlıdır”'),('Florasının kişiden kişiye farklılık gösterdiğine','“kişiden kişiye değişir”'),('Beslenmenin floranın yapısını etkilediğine','“beslenme alışkanlığı… etkileyen etmenlerden biridir”'),('Antibiyotiğin florayı bozabileceğine','“dengeyi bozabilir”')],
 'Her şıkkın dayanağını parçada işaretle.','bağırsak florasının işlevini ve bozulma nedenini')
Z('K-PYAR-04','zor','Dolaylı değinilen konulardan hiç geçmeyeni belirler.','D',
 'Bir cisme baktığımızda onu bulunduğu anda değil, ışığının bize ulaştığı anda görürüz. Güneş’e baktığımızda sekiz dakika öncesini, yakın bir yıldıza baktığımızda yıllar öncesini görürüz. Uzak gökadalarda bu fark milyarlarca yılı bulur. Bu yüzden teleskoplar yalnızca uzağı değil, geçmişi de gösterir: Ne kadar uzağa bakılırsa evrenin o kadar genç hâli görülür. Gökbilimciler bu özelliği, gökadaların zaman içinde nasıl değiştiğini farklı uzaklıktaki örnekleri karşılaştırarak anlamak için kullanır. Yine de görüntü ne kadar eskiyse, o cismin bugün de aynı durumda olduğunu söyleyemeyiz. Gökbilimciler bu nedenle bir görüntüyü yorumlarken ışığın yola çıktığı dönemi de hesaba katar. Böylece aynı anda bakılan farklı uzaklıktaki iki gökada, aslında evrenin farklı çağlarına ait iki fotoğraf gibidir.',
 'Evrenin genişleme hızının zamanla arttığına','Genişleme hızı parçada hiç geçmez; öteki dört konu parçada doğrudan ya da dolaylı işlenir.',
 [('Işığın bize ulaşmasının zaman aldığına','“ışığının bize ulaştığı anda görürüz”'),('Daha uzaktaki cisimlerin daha eski görüntülerinin izlendiğine','“Ne kadar uzağa bakılırsa evrenin o kadar genç hâli görülür”'),('Farklı uzaklıklardaki gökadaların karşılaştırılarak incelendiğine','“farklı uzaklıktaki örnekleri karşılaştırarak”'),('Görüntü ile cismin bugünkü durumunun örtüşmeyebileceğine','“bugün de aynı durumda olduğunu söyleyemeyiz”')],
 'Son cümledeki uyarıyı da bir konu say; sonra şıkları eşle.','ışığın ulaşma süresi nedeniyle uzak cisimlerin geçmişte görülmesini')
Z('K-PYAR-04','zor','Dolaylı değinilen konulardan hiç geçmeyeni belirler.','D',
 'Fosil, geçmişte yaşamış bir canlının kayaç içinde korunmuş izi ya da kalıntısıdır. Ölen bir canlının fosilleşebilmesi için çoğu zaman çabuk gömülmesi gerekir; açıkta kalan kalıntı leşçiller ve çürüme yüzünden kısa sürede yok olur. Bu yüzden fosil kayıtları, yaşamış her türü eşit biçimde temsil etmez: Sert kabuklu ya da kemikli canlılar, yumuşak dokulu canlılara göre çok daha sık fosilleşir. Dolayısıyla bir türün fosili bulunamıyorsa bu onun hiç yaşamadığını göstermez; yalnızca korunma koşullarının uygun olmadığını düşündürebilir. Bu nedenle bilim insanları, fosil kayıtlarındaki boşlukları yorumlarken temkinli davranır ve eksik veriden kesin sonuç çıkarmaktan kaçınır. Dolayısıyla fosil sayısı, geçmişteki canlı çeşitliliğinin kendisini değil, yalnızca korunabilmiş bölümünü yansıtır.',
 'Fosillerin yaşının nasıl belirlendiğine','Yaş belirleme yöntemi parçada hiç geçmez; öteki dört konu doğrudan ya da dolaylı işlenir.',
 [('Fosilleşmenin başlıca koşullarından birine','“çoğu zaman çabuk gömülmesi gerekir”'),('Açıkta kalan kalıntıların neden yok olduğuna','“leşçiller ve çürüme yüzünden”'),('Fosil kayıtlarının türleri aynı ölçüde yansıtmadığına','“yaşamış her türü eşit biçimde temsil etmez”'),('Fosili bulunmayan türleri yorumlarken gereken dikkate','“hiç yaşamadığını göstermez”')],
 'Parçadaki her cümlenin bir şıkla eşleştiğini düşün; eşleşmeyen şık hangisi?','fosillerin oluşumunu ve fosil kayıtlarının eksikliğini')
Z('K-PYAR-04','zor','Dolaylı değinilen konulardan hiç geçmeyeni belirler.','D',
 'Okyanusların yüzeye yakın sularında yaşayan, çoğu zaman çıplak gözle seçilemeyen fitoplanktonlar, fotosentez yapan tek hücreli canlılardır. Karadaki bitkiler gibi karbondioksit alıp oksijen üretirler; Dünya’daki oksijenin önemli bir bölümünün onlardan geldiği düşünülür. Aynı zamanda deniz besin zincirinin ilk halkasıdırlar: Küçük kabuklular onlarla beslenir, balıklar da kabukluları yer. Fitoplanktonun çoğalması ışığa ve suda erimiş besin tuzlarına bağlıdır; kıyıdan aşırı besin tuzu taşınan yerlerde birdenbire aşırı çoğalma görülür ve bu durum su altındaki oksijeni azaltabilir. Bu küçük canlıların bolluğu, hem besin zincirinin hem de gezegenin gaz dengesinin sağlığı açısından yakından izlenir. Uydu görüntüleri, suyun rengindeki değişimden yola çıkarak fitoplankton miktarını geniş alanlarda izlemeye olanak verir.',
 'Fitoplanktonun suyun sıcaklığını düzenlediğine','Sıcaklık düzenlemesi parçada hiç geçmez; öteki dört konu doğrudan ya da dolaylı işlenir.',
 [('Fitoplanktonun fotosentez yapan bir canlı olduğuna','“fotosentez yapan tek hücreli canlılardır”'),('Oksijen üretimine sağladığı katkıya','“oksijenin önemli bir bölümünün onlardan geldiği düşünülür”'),('Deniz besin zincirindeki konumuna','“besin zincirinin ilk halkasıdırlar”'),('Aşırı çoğalmanın sudaki oksijeni azaltabileceğine','“aşırı çoğalma… su altındaki oksijeni azaltabilir”')],
 'Son cümlede de bir konu var; onu da hesaba kat.','fitoplanktonun oksijen üretimini ve besin zincirindeki yerini')

# ---------------- SÖYLENEMEZ (5) ----------------
Z('K-PYAR-05','kolay','Parçanın destekleyemediği yargıyı belirler.','S',
 'Karıncalar, bir kolonide yaşayan sosyal böceklerdir. Kolonide görev paylaşımı vardır: Kraliçe yumurtlar, işçiler yiyecek toplar ve yavruları besler, askerler ise yuvayı korur. Karıncalar yürüdükleri yola kokulu bir madde bırakır; arkadaşları bu izi izleyerek yiyeceğe ulaşır. Tek bir karıncanın yapabildikleri sınırlıdır, ama koloni bir bütün olarak yuvalar kurar, yiyecek depolar ve kendini savunur. Bu iş birliği sayesinde karıncalar, tek başına başarılması güç görevlerin üstesinden gelir.',
 'Koloninin başarısı, bireylerin yeteneğine dayanır.','Parça, tek karıncanın yapabildiklerinin “sınırlı” olduğunu, başarının kolonide toplandığını söyler; şık parçayla çelişir.',
 [('Karıncalar arasında görevlere göre bir iş bölümü bulunur.','“Kolonide görev paylaşımı vardır”'),('Yiyeceğe giden yol, bırakılan koku izleriyle işaretlenir.','“yola kokulu bir madde bırakır”'),('Yuvanın savunulması, askerlerin üstlendiği görevdir.','“askerler ise yuvayı korur”'),('Yumurtlama görevini koloninin kraliçesi üstlenir.','“Kraliçe yumurtlar”')],
 'Parçada tek karıncayla koloni arasında kurulan karşıtlığı bul.','karıncaların koloni hâlinde iş bölümü yapmasını',kok=None)
Z('K-PYAR-05','kolay','Parçanın destekleyemediği yargıyı belirler.','S',
 'Lif, sebze, meyve, baklagil ve tam tahılda bulunan, ama vücudumuzun sindiremediği bir besin öğesidir. Sindirilmediği için enerji sağlamaz; buna karşın sindirim sisteminde önemli işler görür. Bağırsağın düzenli çalışmasına yardım eder, tokluk hissini uzatır ve kana şekerin karışma hızını yavaşlatır. Bu nedenle rafine edilmiş besinler yerine lifli besinleri seçmek, genellikle daha dengeli bir beslenme için önerilir. Uzmanlar, günlük öğünlerde sebze ve meyveye yer vermenin lif alımını artırmanın kolay bir yolu olduğunu belirtir.',
 'Lif, vücuda doğrudan enerji sağlar.','Parça, lifin sindirilmediği için “enerji sağlamadığını” söyler; şık parçayla çelişir.',
 [('Lif, vücudun sindiremediği bir besin öğesidir.','“vücudumuzun sindiremediği bir besin öğesidir”'),('Lif, bağırsağın işleyişine yardımcı olur.','“Bağırsağın düzenli çalışmasına yardım eder”'),('Lifli besinler, tokluk hissini uzatabilir.','“tokluk hissini uzatır”'),('Lif, kandaki şekerin yükselme hızını azaltabilir.','“kana şekerin karışma hızını yavaşlatır”')],
 'Lifin enerjiyle ilişkisini anlatan cümleyi bul.','lifin vücuttaki işlevini')
Z('K-PYAR-05','orta','Parçanın destekleyemediği yargıyı belirler.','S',
 'Ekrana uzun süre bakarken göz kırpma sıklığımız azalır; bu da gözyaşı tabakasının hızla kurumasına yol açar. Sonuçta gözlerde yanma, batma ve bulanık görme şikâyetleri ortaya çıkar. Yakına odaklanmış gözün kasları da sürekli gergin kaldığından yorulur. Ekran kullanımı tümüyle bırakılmadan bu şikâyetler azaltılabilir: Belirli aralıklarla uzağa bakmak ve bilinçli olarak sık göz kırpmak çoğu zaman yeterli olur. Bu şikâyetler çoğu zaman geçicidir; ancak sürekli tekrarlandığında kişinin çalışma veriminin de düşmesine neden olabilir.',
 'Şikâyetleri gidermenin tek yolu ekranı bırakmaktır.','Parça, ekran bırakılmadan da şikâyetlerin azaltılabileceğini söyler; “tek yol” yargısı parçayla çelişir.',
 [('Ekrana bakarken göz kırpma sayısı düşer.','“göz kırpma sıklığımız azalır”'),('Gözyaşı tabakasının kuruması, rahatsızlığa yol açar.','“gözyaşı tabakasının hızla kurumasına yol açar”'),('Yakına odaklanma, göz kaslarını yorabilir.','“kasları da sürekli gergin kaldığından yorulur”'),('Aralıklarla uzağa bakmak, şikâyetleri azaltabilir.','“Belirli aralıklarla uzağa bakmak… yeterli olur”')],
 'Çözüm önerisinin kapsamını gösteren “tümüyle” sözcüğüne dikkat et.','ekran kullanımının göz üzerindeki etkisini')
Z('K-PYAR-05','orta','Parçanın destekleyemediği yargıyı belirler.','S',
 'Gürültü yalnızca rahatsız edici bir ses değildir; uzun süre maruz kalındığında bedeni de etkiler. Yüksek sesli ortamlarda vücut sürekli tetikte kalır, kalp atışı ve kan basıncı yükselebilir. Gece boyunca süren gürültü, uykunun derinleşmesini engeller. Çocuklarda ise gürültülü sınıflarda dikkatin ve okuma becerisinin zayıfladığı gözlenmiştir. İşitme kaybı genellikle ani bir olaydan çok, yıllar içinde biriken maruziyetin sonucudur. Bu nedenle gürültüye alışmak, onun zararından kurtulmak anlamına gelmez.',
 'Gürültüye alışan kişi, bu sesin zararından korunmuş olur.','Parça, alışmanın zarardan kurtulmak anlamına gelmediğini söyler; şık parçayla çelişir.',
 [('Gürültü, kan basıncını yükselten etkenlerden biri olabilir.','“kalp atışı ve kan basıncı yükselebilir”'),('Gece gürültüsü, uykunun niteliğini düşürebilir.','“uykunun derinleşmesini engeller”'),('Gürültülü ortam, çocukların dikkatini zayıflatabilir.','“dikkatin ve okuma becerisinin zayıfladığı gözlenmiştir”'),('İşitme kaybı, çoğunlukla uzun süreli maruziyetin ürünüdür.','“yıllar içinde biriken maruziyetin sonucudur”')],
 'Parçanın son cümlesi “alışmak” konusunda ne diyor?','gürültünün bedene ve öğrenmeye etkisini')
Z('K-PYAR-05','zor','Dolaylı anlatılan yargılardan parçayla çelişeni belirler.','S',
 'Elektrikli araçlar egzoz gazı çıkarmadığı için kentlerdeki hava kirliliğini azaltır. Ancak çevreye etkisini yalnızca yolda ölçmek eksik kalır: Bataryanın üretimi için lityum, kobalt gibi madenlerin çıkarılması ve işlenmesi önemli ölçüde enerji ve su gerektirir. Araç, elektriği kömürle çalışan santrallerden alıyorsa kirlilik egzozdan santral bacasına taşınmış olur. Buna karşılık elektriğin yenilenebilir kaynaklardan gelmesi ve eski bataryaların geri dönüştürülmesi, aracın toplam çevresel yükünü belirgin biçimde düşürür. Dolayısıyla araç ne kadar temiz görünürse görünsün, sonuç onu besleyen enerjinin kaynağına da bağlıdır. Bu yüzden araçların çevre karnesi hazırlanırken üretimden geri dönüşüme kadar tüm yaşam döngüsü birlikte ele alınmalıdır. Bu bütünsel bakış, araç türleri arasında adil bir karşılaştırma yapmanın ön koşuludur.',
 'Çevre etkisi, yalnızca yolda çıkan gazla belirlenir.','Parça, etkiyi “yalnızca yolda ölçmenin eksik kaldığını” söyler; şık parçayla çelişir.',
 [('Elektrikli araçlar, kent içi havanın kirlenmesini azaltmaya katkı sağlar.','“kentlerdeki hava kirliliğini azaltır”'),('Batarya üretimi, çevresel bir maliyet doğuran aşamadır.','“önemli ölçüde enerji ve su gerektirir”'),('Kömürden elde edilen elektrik, kirliliği başka bir yere taşıyabilir.','“egzozdan santral bacasına taşınmış olur”'),('Eski bataryaların geri dönüşümü, toplam çevre yükünü azaltabilir.','“geri dönüştürülmesi… toplam çevresel yükünü… düşürür”')],
 'Parçada “eksik kalır” diyen ifadeyi bul; hangi şık onu yok sayıyor?','elektrikli araçların çevresel etkisinin yalnızca yolda ölçülemeyeceğini')

# ---------------- ULAŞILABİLİR / ÇIKARILABİLİR (5) ----------------
Z('K-PYAR-06','kolay','Parçadan kesin çıkarımı belirler.','C',
 'Birçok kişi, hatırlamak kolay olsun diye doğum tarihi ya da adı gibi kişisel bilgilerden parola üretir. Oysa bu bilgiler başkaları tarafından da kolayca öğrenilebilir ve saldırganlar parola tahmin ederken ilk bu bilgileri dener. Uzun, tahmin edilmesi zor ve her hesap için ayrı bir parola, tek bir hesabın ele geçirilmesinin diğerlerine sıçramasını engeller. Parolaları akılda tutmak zor geliyorsa bunları güvenli bir parola yöneticisinde saklamak da bir çözümdür.',
 'Kişisel bilgilerden oluşan parolalar, güvenlik açısından zayıftır.','Parça, bu bilgilerin kolayca öğrenilebildiğini ve saldırganların ilk onları denediğini söyler; bu da bu tür parolaların zayıf olduğunu gösterir.',
 [('Parola ne kadar uzunsa hesap o kadar kesin olarak güvendedir.','Parça uzun parolanın yararını söyler; “kesin güvenlik” iddiası parçada yoktur.'),('Parola yöneticilerine hiçbir koşulda saldırı yapılamaz.','Parça yöneticiyi “güvenli” bir çözüm olarak anar; “hiçbir koşulda saldırı yapılamaz” iddiası parçada yoktur.'),('Tek parolayı her hesapta kullanmak, güvenliği artıran bir yöntemdir.','Parça her hesap için ayrı parolayı önerir; şık parçanın tersini söyler.'),('Saldırganlar, yalnızca kişisel bilgilerden yola çıkarak parola tahmin eder.','Parça saldırganların “ilk” bu bilgileri denediğini söyler; “yalnızca” aşırı bir genellemedir.')],
 'Parçada saldırganın ilk neyi denediğini bul; bu bilgiden hangi sonuç çıkar?','kişisel bilgilerden parola üretmenin sakıncasını')
Z('K-PYAR-06','orta','Parçadan kesin çıkarımı belirler.','C',
 'Öğrendiğimiz bilginin unutulma hızı ilk günlerde en yüksektir; tekrar yapılmazsa bilginin büyük bölümü birkaç gün içinde silinir. Ancak her tekrar, unutma eğrisini yatıklaştırır. Bu yüzden aynı süreyi tek oturumda yığmak yerine günlere yaymak, bilginin kalıcı hâle gelmesinde daha etkili olur. Tekrarların arası, bilgiyi hâlâ hatırlayabildiğimiz ama biraz zorlandığımız ana denk geldiğinde en yararlı sonucu verir. Bu bulgu, sınav öncesinde yığılan çalışmanın neden çoğu zaman kısa süreli bir etki bıraktığını da açıklar.',
 'Çalışmayı günlere yaymak, kalıcılığı artıran bir yoldur.','Parça, süreyi günlere yaymanın bilginin kalıcı hâle gelmesinde “daha etkili” olduğunu söyler.',
 [('Tek oturumda çalışmak, her konuda başarısızlığa yol açar.','Parça tek oturumun daha az etkili olduğunu söyler; “her konuda başarısızlık” aşırı bir genellemedir.'),('Bilgi, tekrar edilmese bile ilk haftadan sonra unutulmaz.','Parça tekrarsız bilginin birkaç günde büyük ölçüde silindiğini söyler; şık parçanın tersini söyler.'),('Tekrar sayısı arttıkça öğrenme her koşulda aynı oranda hızlanır.','Parça tekrarın unutmayı yavaşlattığını söyler; “her koşulda aynı oranda hızlanır” iddiası parçada yoktur.'),('Unutma hızı, bilginin zorluk düzeyine göre değişir.','Parça unutma hızını zamana bağlı anlatır; zorluk düzeyinden hiç söz etmez.')],
 'Parçadaki karşılaştırmayı bul: iki çalışma biçiminden hangisi “daha etkili”?','aralıklı tekrarın kalıcı öğrenmedeki yerini')
Z('K-PYAR-06','orta','Parçadan kesin çıkarımı belirler.','C',
 'Sulak alanlar, bataklık, sazlık ve gölet gibi suyun yıl boyu ya da mevsimlik olarak karayı kapladığı bölgelerdir. Yağışlı dönemde fazla suyu sünger gibi emer, kurak dönemde yavaş yavaş bırakır; böylece taşkın riskini azaltır. Bitki örtüsü, sudaki kirleticileri tutup suyu süzer. Pek çok kuş türü göç yolunda dinlenmek ve beslenmek için bu alanları kullanır. Buna rağmen sulak alanlar tarım ve yerleşim için kurutuldukça hızla azalıyor.',
 'Sulak alanların kurutulması taşkın riskini artırabilir.','Parça, sulak alanların fazla suyu emerek taşkın riskini azalttığını söyler; kurutulduklarında bu koruma kalkacağından risk artabilir.',
 [('Sulak alanlar yalnızca kuşlar için önem taşır.','Parça taşkın önleme ve su süzme gibi başka işlevleri de sayar; “yalnızca kuşlar” yargısı parçayla çelişir.'),('Taşkın riski, yalnızca sulak alanlar sayesinde önlenir.','Parça sulak alanların taşkını azalttığını söyler; “tek önlem” olduklarını söylemez.'),('Sulak alanlar, yağışı artırarak kuraklığı engeller.','Parça sulak alanların yağışı artırdığından söz etmez; yalnızca suyu tutup bıraktığını söyler.'),('Kurutulan sulak alanların tamamı tarıma ayrılmıştır.','Parça tarım ve yerleşimi birlikte anar; “tamamı tarım” yargısı parçada yoktur.')],
 'Sulak alanın yağışlı ve kurak dönemdeki işlevini anlatan cümleden hareket et.','sulak alanların taşkını önleyen ve suyu süzen işlevini')
Z('K-PYAR-06','orta','Parçadan kesin çıkarımı belirler.','C',
 'Depremde önce daha az zarar veren P dalgaları, ardından yıkıcı S dalgaları yayılır. İki dalganın hızı farklıdır; bu yüzden merkez üssünden uzaklaştıkça aralarındaki süre açılır. Erken uyarı sistemleri, P dalgalarını algılayıp bunu merkez üssünden uzaktaki kentlere hemen bildirir. Elektrik sinyali yer sarsıntısından çok daha hızlı yol aldığından, uzak kentler yıkıcı dalgalar gelmeden saniyeler önce uyarı alabilir. Merkez üssüne çok yakın yerlerde ise bu süre neredeyse sıfıra iner.',
 'Merkez üssüne uzak yerlerin hazırlık süresi daha uzundur.','Parça, uzaklaştıkça iki dalga arasındaki sürenin açıldığını ve yakın yerlerde sürenin sıfıra indiğini söyler; uzak yerlerin daha uzun süresi olacağı çıkar.',
 [('Erken uyarı sistemleri, depremi önceden tahmin edebilir.','Parça sistemlerin P dalgasını algıladığını söyler; depremi önceden tahmin ettiğini söylemez.'),('Merkez üssüne yakın kentler, uyarıdan en çok yararlanır.','Parça yakın yerlerde süreyi neredeyse sıfır gösterir; şık parçanın tersini söyler.'),('P dalgaları, yapılara S dalgalarından daha çok zarar verir.','Parça S dalgalarını “yıkıcı”, P dalgalarını daha az zarar veren olarak anar; şık parçanın tersini söyler.'),('Elektrik sinyali, yer sarsıntısından daha yavaş ilerler.','Parça elektrik sinyalinin çok daha hızlı olduğunu söyler; şık parçanın tersini söyler.')],
 'Parçada uzaklık ile uyarı süresi arasındaki ilişkiyi bul.','deprem erken uyarı sistemlerinin dalga hızı farkından yararlanmasını')
Z('K-PYAR-06','zor','Parçadan kesin çıkarımı belirler.','C',
 'Toprağı bir arada tutan şey, çoğunlukla üzerindeki bitki örtüsüdür. Ağaç kökleri toprağı sarar, yapraklar yağmur damlalarının toprağa çarpma hızını keser ve ölü örtü suyun yüzeyde hızla akmasını engeller. Orman, tarla açmak için yok edildiğinde bu koruma birdenbire ortadan kalkar; yağış, toprağın verimli üst tabakasını yıkayıp akarsulara taşır. Verimli tabaka yüzyıllarda oluşur, ancak birkaç yılda yitirilebilir. Üstelik taşınan çamur baraj göllerini doldurur ve akarsu ekosistemini bozar. Bu nedenle eğimli arazilerde ağaçlandırma, yalnızca orman için değil, aşağıdaki yerleşimin su güvenliği için de önlemdir. Bu zincirleme etki, tek bir bölgedeki orman kaybının çok uzaktaki sulama ve içme suyu kaynaklarına da yansıyabileceğini gösterir. Bu nedenle toprak koruma çalışmaları çoğu zaman havza ölçeğinde planlanır.',
 'Bitki örtüsünü korumak, baraj göllerinin dolmasını da yavaşlatır.','Parça, taşınan çamurun baraj göllerini doldurduğunu ve bitki örtüsünün toprağı tuttuğunu söyler; bitki örtüsünü korumak çamur taşınımını azaltacağından dolmayı yavaşlatır.',
 [('Orman yok edilerek tarla açmak, uzun vadede toprağın verimini artırır.','Parça orman yok edilince verimli üst tabakanın yitirildiğini söyler; şık parçanın tersini söyler.'),('Verimli üst tabaka kaybedilirse birkaç yıl içinde yeniden oluşur.','Parça tabakanın yüzyıllarda oluştuğunu söyler; şık parçanın tersini söyler.'),('Toprak aşınması, yalnızca ağaçsız bölgelerde görülen bir sorundur.','Parça aşınmanın bitki örtüsü yok edilince ortaya çıktığını anlatır; “yalnızca ağaçsız bölgeler” yargısı parçada yoktur.'),('Yağmur damlalarının çarpma hızı, aşınmanın tek nedenidir.','Parça aşınmada kök, yaprak ve ölü örtünün birlikte rol oynadığını anlatır; “tek neden” iddiası parçada yoktur.')],
 'Çamurun baraj gölleriyle ilişkisini ve bitki örtüsünün görevini birlikte düşün.','bitki örtüsünün toprağı koruyan işlevini')
bitir(Q)
